<?php
declare(strict_types=1);
require dirname(__DIR__).'/bootstrap.php';require_once dirname(__DIR__).'/app/Auth/SessionUser.php';require_once dirname(__DIR__).'/app/UI/Workspace.php';require_once dirname(__DIR__).'/app/UI/MessageHtml.php';require_once dirname(__DIR__).'/app/UI/Conversation.php';require_once dirname(__DIR__).'/app/Mail/Reception.php';
header('Cache-Control: no-store');header("Content-Security-Policy: default-src 'self'; style-src 'self'; frame-src 'self'; img-src 'self' data: https:; form-action 'self'; base-uri 'none'; frame-ancestors 'self'");$db=tnl_db();$identity=\TNL\Auth\SessionUser::require($db);\TNL\Mail\Reception::init($db);$admin=$identity['role']==='admin';$message=null;if(isset($_GET['id'])){$message=\TNL\Mail\Reception::read($db,(int)$_GET['id'],$identity['id'],$admin);if(!$message){http_response_code(404);exit('Mensaje no disponible.');}}$q=$db->prepare('SELECT id,sender,subject,created_at,read_at FROM reception_messages'.($admin?'':' WHERE assigned_user=?').' ORDER BY id DESC LIMIT 100');$q->execute($admin?[]:[$identity['id']]);$messages=$q->fetchAll(PDO::FETCH_ASSOC);
?><!doctype html><html lang="es"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Recepción asignada · TNL Mail</title><link rel="stylesheet" href="assets/app.css?v=0.10.1"><script src="assets/workspace.js?v=0.10.1" defer></script><script src="assets/composer.js?v=0.10.1" defer></script></head><body><div class="layout"><?php \TNL\UI\Workspace::sidebar($identity['role'],'reception-mail',$identity['name']);?><main class="main"><h1>Recepción asignada</h1><?php if($message):?><article class="panel message-panel"><header class="message-heading"><div><h2><?=tnl_escape($message['subject'])?></h2><p><?=tnl_escape($message['sender'].' · '.$message['created_at'])?></p></div><?php if(!$admin):?><a class="button" data-compose-modal href="mail.php?reception=<?=(int)$message['id']?>&amp;compose=1&amp;modal=1">Responder</a><?php endif;?></header><?php if($message['html']):?><iframe class="mail-html-view" title="Contenido recibido" sandbox="allow-same-origin allow-popups allow-popups-to-escape-sandbox" data-mail-view srcdoc="<?=tnl_escape(\TNL\UI\MessageHtml::document(['html'=>$message['html'],'inline_images'=>json_decode($message['images'],true)],true))?>"></iframe><?php else:?><pre class="message-text"><?=tnl_escape($message['body'])?></pre><?php endif;?></article><?php $threadQuery=$db->prepare('SELECT * FROM reception_messages WHERE token=?'.($admin?'':' AND assigned_user=?').' ORDER BY id DESC LIMIT 30');$threadQuery->execute($admin?[$message['token']]:[$message['token'],$identity['id']]);$thread=[];foreach($threadQuery->fetchAll(PDO::FETCH_ASSOC) as $entry)$thread[]=['headers'=>json_decode($entry['headers'],true),'body'=>$entry['body'],'html'=>$entry['html'],'inline_images'=>json_decode($entry['images'],true)];echo '<div data-live-region="reception-thread">';\TNL\UI\Conversation::render($thread,true,$message['message_id']);echo '</div>';?><?php endif;?><section class="panel mail-surface" data-live-region="reception-list"><?php foreach($messages as $m):?><a class="mail-row" href="?id=<?=(int)$m['id']?>"><span><?=tnl_escape($m['sender'])?></span><span><?=tnl_escape($m['subject'])?><?=$m['read_at']?'':' · Nuevo'?></span><time><?=tnl_escape($m['created_at'])?></time></a><?php endforeach;?><?php if(!$messages):?><p class="empty-state">No hay mensajes asignados.</p><?php endif;?></section></main></div></body></html>
